arguments.command:
RAILS_ENV=test bundle exec rails runner '
require "fabrication"
require "faker"
Rails.root.glob("spec/support/**/*.rb").each { |f| require f }
Rails.root.glob("spec/fabricators/**/*.rb").each { |f| require f }
Sidekiq::Testing.fake!

def profile(name, &block)
  # warmup
  ActiveRecord::Base.transaction do
    block.call
    raise ActiveRecord::Rollback
  end
  queries = []
  sub = ActiveSupport::Notifications.subscribe("sql.active_record") do |_, _, _, _, payload|
    next if payload[:name] == "SCHEMA" || payload[:sql].start_with?("SAVEPOINT", "RELEASE", "BEGIN", "ROLLBACK")
    queries << payload[:sql].split.first(3).join(" ")
  end
  t0 = Process.clock_gettime(Process::CLOCK_MONOTONIC)
  ActiveRecord::Base.transaction do
    block.call
    raise ActiveRecord::Rollback
  end
  dt = (Process.clock_gettime(Process::CLOCK_MONOTONIC) - t0) * 1000
  ActiveSupport::Notifications.unsubscribe(sub)
  puts format("%-25s %6.2f ms | %3d queries | %s", name, dt, queries.size, queries.tally.inspect)
end

profile("account") { Fabricate(:account) }
profile("remote_account") { Fabricate(:remote_account) }
profile("user") { Fabricate(:user) }
profile("status") { Fabricate(:status) }
profile("status(with acct)") { a = Fabricate(:account); Fabricate(:status, account: a) }
profile("notification") { Fabricate(:notification) }
profile("preview_card") { Fabricate(:preview_card) }
profile("report") { Fabricate(:report) }
profile("custom_emoji") { Fabricate(:custom_emoji) }
profile("collection") { Fabricate(:collection) }
'

