    raise ActiveRecord::Rollback
  end
  dt = (Process.clock_gettime(Process::CLOCK_MONOTONIC) - t0) * 1000 / n
  ActiveSupport::Notifications.unsubscribe(sub)
  puts format("%-25s %6.2f ms | %4.1f queries", name, dt, queries.to_f / n)
